1	import { getBridgeConfig, Network } from "./consts/bridgeRoutes";
2	import { getVeaInbox, getVeaOutbox } from "./utils/ethers";
3	import { FallbackRpcProvider } from "./utils/fallbackProvider";
4	import { FallbackProviderV5 } from "./utils/fallbackProviderV5";
5	import { setEpochRange } from "./utils/epochHandler";
6	import { defaultEmitter } from "./utils/emitter";
7	import { BotEvents } from "./utils/botEvents";
8	import { initialize as initializeLogger } from "./utils/logger";
9	import { ShutdownSignal } from "./utils/shutdown";
10	import { getBotPath, BotPaths, getNetworkConfig, NetworkConfig } from "./utils/botConfig";
11	import { getClaim } from "./utils/claim";
12	import { CheckAndClaimParams, checkAndClaim } from "./helpers/claimer";
13	import { ChallengeAndResolveClaimParams, challengeAndResolveClaim } from "./helpers/validator";
14	import { saveSnapshot, SaveSnapshotParams } from "./helpers/snapshot";
15	import { getTransactionHandler } from "./utils/transactionHandlers";
16	import { validateEnvironment } from "./utils/envValidation";
17	
18	const CYCLE_DELAY_MS = 2 * 60 * 1000; // 2 minutes
19	
20	/**
21	 * @file This file contains the logic for watching bridge and validating/resolving for claims.
22	 *
23	 * @param shutDownSignal - The signal to shut down the watcher
24	 * @param emitter - The emitter to emit events
25	 *
26	 */
27	
28	export const watch = async (
29	  shutDownSignal: ShutdownSignal = new ShutdownSignal(),
30	  emitter: typeof defaultEmitter = defaultEmitter
31	) => {
32	  initializeLogger(emitter);
33	  // Validate the whole environment before anything else, including before the
34	  // first heartbeat: a bot that reports "started" and then dies on a missing
35	  // variable looks alive to whatever is watching it.
36	  const validatedEnv = await validateEnvironment();
37	  emitter.emit(BotEvents.ENV_VALIDATED, validatedEnv.signerAddress, validatedEnv.chainIds, validatedEnv.networks);
38	  for (const warning of validatedEnv.warnings) emitter.emit(BotEvents.ENV_WARNING, warning);
39	  const cliCommand = process.argv;
40	  const { path, toSaveSnapshot } = getBotPath({ cliCommand });
41	  const networkConfigs = getNetworkConfig();
42	  emitter.emit(BotEvents.STARTED, path, networkConfigs[0].networks);
43	  const transactionHandlers: { [key: string]: any } = {};
44	  const toWatch: { [key: string]: { count: number; epochs: number[] } } = {};
45	  while (!shutDownSignal.getIsShutdownSignal()) {
46	    for (const networkConfig of networkConfigs) {
47	      await processNetwork(path, toSaveSnapshot, networkConfig, transactionHandlers, toWatch, emitter);
48	    }
49	    await wait(CYCLE_DELAY_MS);
50	  }
51	};
52	
53	async function processNetwork(
54	  path: number,
55	  toSaveSnapshot: boolean,
56	  networkConfig: NetworkConfig,
57	  transactionHandlers: { [key: string]: any },
58	  toWatch: { [key: string]: { count: number; epochs: number[] } },
59	  emitter: typeof defaultEmitter
60	): Promise<void> {
61	  const { chainId, networks } = networkConfig;
62	  const { routeConfig, inboxRPC, outboxRPC, routerRPC } = getBridgeConfig(chainId);
63	  for (const network of networks) {
64	    emitter.emit(BotEvents.WATCHING, chainId, network);
65	    const networkKey = `${chainId}_${network}`;
66	    if (!toWatch[networkKey]) {
67	      toWatch[networkKey] = { count: -1, epochs: [] };
68	    }
69	    const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
70	    let veaOutboxLatestBlock = await veaOutboxProvider.getBlock("latest");
71	
72	    // If the watcher has already started, only check the latest epoch
73	    if (network == Network.DEVNET) {
74	      toWatch[networkKey].epochs = [Math.floor(veaOutboxLatestBlock.timestamp / routeConfig[network].epochPeriod)];
75	    } else if (toWatch[networkKey].epochs.length == 0) {
76	      const epochRange = setEpochRange({
77	        chainId,
78	        currentTimestamp: veaOutboxLatestBlock.timestamp,
79	        epochPeriod: routeConfig[network].epochPeriod,
80	      });
81	      toWatch[networkKey].epochs = epochRange;
82	    }
83	
84	    await processEpochsForNetwork({
85	      chainId,
86	      path,
87	      toSaveSnapshot,
88	      networkKey,
89	      network,
90	      routeConfig,
91	      inboxRPC,
92	      outboxRPC,
93	      routerRPC,
94	      toWatch,
95	      transactionHandlers,
96	      emitter,
97	    });
98	    const currentLatestBlock = await veaOutboxProvider.getBlock("latest");
99	    const currentClaimableEpoch = Math.floor(currentLatestBlock.timestamp / routeConfig[network].epochPeriod) - 1;
100	
101	    const toWatchEpochs = toWatch[networkKey];
102	    const lastEpochInToWatch = toWatchEpochs[toWatchEpochs.epochs.length - 1];
103	    if (currentClaimableEpoch > lastEpochInToWatch) {
104	      toWatch[networkKey].epochs.push(currentClaimableEpoch);
105	    }
106	  }
107	}
108	
109	interface ProcessEpochParams {
110	  chainId: number;
111	  path: number;
112	  toSaveSnapshot: boolean;
113	  networkKey: string;
114	  network: Network;
115	  routeConfig: any;
116	  inboxRPC: string[];
117	  outboxRPC: string[];
118	  routerRPC: string[] | undefined;
119	  toWatch: { [key: string]: { count: number; epochs: number[] } };
120	  transactionHandlers: { [key: string]: any };
121	  emitter: typeof defaultEmitter;
122	}
123	async function processEpochsForNetwork({
124	  chainId,
125	  path,
126	  toSaveSnapshot,
127	  networkKey,
128	  network,
129	  routeConfig,
130	  inboxRPC,
131	  outboxRPC,
132	  routerRPC,
133	  toWatch,
134	  transactionHandlers,
135	  emitter,
136	}: ProcessEpochParams) {
137	  const privKey = process.env.PRIVATE_KEY;
138	  // v6 providers for the typechain contract connections (the inbox chainId is detected via the fallback transport).
139	  const veaInboxContractProvider = new FallbackRpcProvider(inboxRPC, emitter);
140	  const veaOutboxContractProvider = new FallbackRpcProvider(outboxRPC, emitter, chainId);
141	  const veaInbox = getVeaInbox(
142	    routeConfig[network].veaInbox.address,
143	    privKey,
144	    veaInboxContractProvider,
145	    chainId,
146	    network
147	  );
148	  const veaOutbox = getVeaOutbox(
149	    routeConfig[network].veaOutbox.address,
150	    privKey,
151	    veaOutboxContractProvider,
152	    chainId,
153	    network
154	  );
155	  // v5 providers for the standalone reads / Arbitrum SDK path.
156	  const veaInboxProvider = new FallbackProviderV5(inboxRPC, emitter);
157	  const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
158	  const veaRouterProvider = routerRPC && routerRPC.length > 0 ? new FallbackProviderV5(routerRPC, emitter) : undefined;
159	  let i = toWatch[networkKey].epochs.length - 1;
160	  let latestEpoch = toWatch[networkKey].epochs[i];
161	  const currentEpoch = Math.floor(Date.now() / (1000 * routeConfig[network].epochPeriod));
162	  if (latestEpoch != currentEpoch - 1 && network != Network.DEVNET) {
163	    toWatch[networkKey].epochs.push(currentEpoch - 1);
164	    latestEpoch = currentEpoch - 1;
165	    i++;
166	  }
167	  // Checks and saves the snapshot if needed
168	  if (toSaveSnapshot) {
169	    const TransactionHandler = getTransactionHandler(chainId, network) as any;
170	    const txnHandlerKey = `${routeConfig[network].veaInbox.address}_${currentEpoch}`;
171	    const transactionHandler =
172	      transactionHandlers[currentEpoch] ||
173	      new TransactionHandler({
174	        network,
175	        epoch: currentEpoch,
176	        veaInbox,
177	        veaOutbox,
178	        veaInboxProvider,
179	        veaOutboxProvider,
180	        veaRouterProvider,
181	        emitter,
182	      });
183	    const { updatedTransactionHandler, latestCount } = await saveSnapshot({
184	      chainId,
185	      veaInbox,
186	      veaOutbox,
187	      veaInboxProvider,
188	      veaOutboxProvider,
189	      network,
190	      epochPeriod: routeConfig[network].epochPeriod,
191	      count: toWatch[networkKey].count,
192	      transactionHandler,
193	    } as SaveSnapshotParams);
194	    const count = toWatch[networkKey].count;
195	    if (count == -1 || count != latestCount) {
196	      transactionHandlers[txnHandlerKey] = updatedTransactionHandler;
197	      toWatch[networkKey].count = latestCount;
198	    }
199	  }
200	
201	  while (i >= 0) {
202	    const epoch = toWatch[networkKey].epochs[i];
203	    const claim = await getClaim({
204	      network,
205	      chainId,
206	      veaOutbox,
207	      veaOutboxProvider,
208	      epoch,
209	      epochPeriod: routeConfig[network].epochPeriod,
210	      emitter,
211	    });
212	
213	    let updatedTransactions;
214	    if (path > BotPaths.CLAIMER && claim != null) {
215	      const checkAndChallengeResolveDeps: ChallengeAndResolveClaimParams = {
216	        chainId,
217	        claim,
218	        epoch,
219	        epochPeriod: routeConfig[network].epochPeriod,
220	        veaInbox,
221	        veaInboxProvider,
222	        veaOutboxProvider,
223	        veaRouterProvider,
224	        veaOutbox,
225	        transactionHandler: transactionHandlers[epoch],
226	        emitter,
227	      };
228	      updatedTransactions = await challengeAndResolveClaim(checkAndChallengeResolveDeps);
229	    }
230	    if (path == BotPaths.CLAIMER || path == BotPaths.BOTH) {
231	      const checkAndClaimParams: CheckAndClaimParams = {
232	        network,
233	        chainId,
234	        claim,
235	        epoch,
236	        epochPeriod: routeConfig[network].epochPeriod,
237	        veaInbox,
238	        veaInboxProvider,
239	        veaOutboxProvider,
240	        veaOutbox,
241	        transactionHandler: transactionHandlers[epoch],
242	        emitter,
243	      };
