1	import { JsonRpcProvider, Block } from "@ethersproject/providers";
2	import { SequencerInbox } from "@arbitrum/sdk/dist/lib/abi/SequencerInbox";
3	import { NodeInterface__factory } from "@arbitrum/sdk/dist/lib/abi/factories/NodeInterface__factory";
4	import { NodeInterface } from "@arbitrum/sdk/dist/lib/abi/NodeInterface";
5	import { NODE_INTERFACE_ADDRESS } from "@arbitrum/sdk/dist/lib/dataEntities/constants";
6	import { getArbitrumNetwork } from "@arbitrum/sdk";
7	import { SequencerInbox__factory } from "@arbitrum/sdk/dist/lib/abi/factories/SequencerInbox__factory";
8	import { defaultEmitter } from "../utils/emitter";
9	import { BotEvents } from "../utils/botEvents";
10	import { findFirstLog } from "./logScanner";
11	
12	// https://github.com/prysmaticlabs/prysm/blob/493905ee9e33a64293b66823e69704f012b39627/config/params/mainnet_config.go#L103
13	const slotsPerEpochEth = 32;
14	const secondsPerSlotEth = 12;
15	
16	export interface SettledReadBlocks {
17	  inboxBlock: number;
18	  outboxBlock: number;
19	}
20	
21	export interface ResolveSettledReadBlocksParams {
22	  inboxProvider: JsonRpcProvider;
23	  // L1/router provider used only to anchor Arbitrum's finality (that the
24	  // Arbitrum "finalized" block is posted in a finalized L1 batch). For routes
25	  // where the outbox does not live on this chain (e.g. arbToGnosis, where
26	  // this is Sepolia but the outbox is on Chiado), it is NOT a valid source for
27	  // outbox-chain block numbers.
28	  outboxProvider: JsonRpcProvider;
29	  // The actual outbox chain's provider, used to read its own "finalized"
30	  // block. Defaults to the L1/router finalized block above for routes where
31	  // the outbox lives on that same chain (arbToEth).
32	  outboxChainProvider?: JsonRpcProvider;
33	  epoch: number;
34	  epochPeriod: number;
35	  emitter?: typeof defaultEmitter;
36	  fetchBlocksAndCheckFinality?: typeof getBlocksAndCheckFinality;
37	}
38	
39	/**
40	 * Resolve the blocks at which this epoch's state can be read as settled.
41	 *
42	 * Two conditions have to hold before a read can be staked on:
43	 *
44	 *  - the block cannot be reorged away, so we anchor to the `finalized` head on
45	 *    both chains;
46	 *  - the block must sit at or after `(epoch + 1) * epochPeriod`, because
47	 *    `snapshots[epoch]` is still being written during epoch E.
48	 *
49	 * When either fails the epoch is simply not decidable yet: callers skip it and
50	 * try again next cycle rather than acting on unsettled state.
51	 *
52	 * @returns The blocks to pin reads to, or null if the epoch is not yet decidable
53	 */
54	export const resolveSettledReadBlocks = async ({
55	  inboxProvider,
56	  outboxProvider,
57	  outboxChainProvider,
58	  epoch,
59	  epochPeriod,
60	  emitter = defaultEmitter,
61	  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
62	}: ResolveSettledReadBlocksParams): Promise<SettledReadBlocks | null> => {
63	  const finality = await fetchBlocksAndCheckFinality(outboxProvider, inboxProvider, epoch, epochPeriod, emitter);
64	  // Checked before destructuring: this returns undefined on an unresolvable
65	  // chain state, and destructuring that throws past every caller's guard.
66	  if (!finality) {
67	    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
68	    return null;
69	  }
70	  const [inboxFinalized, l1Finalized, finalityIssueFlagArb, finalityIssueFlagEth] = finality;
71	  if (finalityIssueFlagArb || finalityIssueFlagEth) {
72	    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
73	    return null;
74	  }
75	
76	  const epochBoundary = (epoch + 1) * epochPeriod;
77	  if (inboxFinalized.timestamp < epochBoundary) {
78	    emitter.emit(BotEvents.EPOCH_NOT_SETTLED, epoch, inboxFinalized.timestamp, epochBoundary);
79	    return null;
80	  }
81	
82	  // The outbox contract is not necessarily on the L1/router chain used above
83	  // to anchor Arbitrum's finality, so its finalized block must be read
84	  // separately from the chain it actually lives on.
85	  const outboxFinalized = outboxChainProvider ? await outboxChainProvider.getBlock("finalized") : l1Finalized;
86	
87	  return { inboxBlock: inboxFinalized.number, outboxBlock: outboxFinalized.number };
88	};
89	
90	/**
91	 * The sequencer's maximum backdating window, in seconds.
92	 *
93	 * `maxTimeVariation()` returns four values -- [delayBlocks, futureBlocks,
94	 * delaySeconds, futureSeconds] -- so coercing the whole result yields NaN, which
95	 * then silently poisons every block range derived from it.
96	 *
97	 * @returns delaySeconds from the sequencer inbox
98	 */
99	const getSequencerDelaySeconds = async (sequencer: SequencerInbox): Promise<number> => {
100	  const { delaySeconds } = await sequencer.maxTimeVariation();
101	  return Number(delaySeconds);
102	};
103	
104	/**
105	 * This function checks the finality of the blocks on Arbitrum and Ethereum.
106	 * It returns the latest/finalized block on Arbitrum(found on Ethereum) and Ethereum and a flag indicating if there is a finality issue on Ethereum.
107	 *
108	 * @param EthProvider Ethereum provider
109	 * @param ArbProvider Arbitrum provider
110	 * @param veaEpoch epoch number of the claim to be fetched
111	 * @param veaEpochPeriod epoch period of the claim to be fetched
112	 *
113	 * @returns [Arbitrum block, Ethereum block, finalityIssueFlagArb, finalityIssueFlagEth]
114	 * */
115	const getBlocksAndCheckFinality = async (
116	  EthProvider: JsonRpcProvider,
117	  ArbProvider: JsonRpcProvider,
118	  veaEpoch: number,
119	  veaEpochPeriod: number,
120	  emitter: typeof defaultEmitter
121	): Promise<[Block, Block, boolean, boolean] | undefined> => {
122	  const currentEpoch = Math.floor(Date.now() / 1000 / veaEpochPeriod);
123	
124	  const l2Network = await getArbitrumNetwork(ArbProvider);
125	  const sequencer = SequencerInbox__factory.connect(l2Network.ethBridge.sequencerInbox, EthProvider);
126	  const maxDelaySeconds = await getSequencerDelaySeconds(sequencer);
127	  const blockFinalizedArb = (await ArbProvider.getBlock("finalized")) as Block;
128	  const blockFinalizedEth = (await EthProvider.getBlock("finalized")) as Block;
129	  if (
130	    currentEpoch - veaEpoch > 2 &&
131	    blockFinalizedArb.timestamp > veaEpoch * veaEpochPeriod &&
132	    blockFinalizedEth.timestamp > veaEpoch * veaEpochPeriod
133	  ) {
134	    return [blockFinalizedArb, blockFinalizedEth, false, false];
135	  }
136	  const finalityBuffer = 300; // 5 minutes, allows for network delays
137	  const maxFinalityTimeSecondsEth = slotsPerEpochEth * 2 * secondsPerSlotEth; // finalization after 2 justified epochs
138	
139	  let finalityIssueFlagArb = false;
140	  let finalityIssueFlagEth = false;
141	
142	  // check latest arb block to see if there are any sequencer issues
143	  let blockLatestArb = (await ArbProvider.getBlock("latest")) as Block;
144	
145	  const maxDelayInSeconds = 7 * 24 * 60 * 60; // 7 days
146	  let blockoldArb = (await ArbProvider.getBlock(blockLatestArb.number - 100)) as Block;
147	  const arbAverageBlockTime = (blockLatestArb.timestamp - blockoldArb.timestamp) / 100;
148	  const fromBlockArbFinalized = blockFinalizedArb.number - Math.ceil(maxDelayInSeconds / arbAverageBlockTime);
149	  // to performantly query the sequencerInbox's SequencerBatchDelivered event on Eth, we limit the block range
150	  // we use the heuristic that. delta blocknumber <= delta timestamp / secondsPerSlot
151	  // Arb: -----------x                   <-- Finalized
152	  //                 ||
153	  //                 \/
154	  // Eth: -------------------------x     <-- Finalized
155	  //            /\
156	  //            ||<---------------->     <-- Math.floor((timeDiffBlockFinalizedArbL1 + maxDelaySeconds) / secondsPerSlotEth)
157	  //         fromBlockEth
158	
159	  const timeDiffBlockFinalizedArbL1 = blockFinalizedEth.timestamp - blockFinalizedArb.timestamp;
160	  const fromBlockEthFinalized =
161	    blockFinalizedEth.number - Math.floor((timeDiffBlockFinalizedArbL1 + maxDelaySeconds) / secondsPerSlotEth);
162	
163	  let blockFinalizedArbToL1Block = await ArbBlockToL1Block(
164	    ArbProvider,
165	    sequencer,
166	    blockFinalizedArb,
167	    fromBlockEthFinalized,
168	    fromBlockArbFinalized,
169	    false
170	  );
171	
172	  if (!blockFinalizedArbToL1Block) {
173	    emitter.emit(BotEvents.FINALITY_ERROR, "Arbitrum finalized block is not found on L1.");
174	    finalityIssueFlagArb = true;
175	  } else if (Math.abs(blockFinalizedArbToL1Block[0].timestamp - blockFinalizedArb.timestamp) > 1800) {
176	    // The L2 timestamp is drifted from the L1 timestamp in which the L2 block is posted.
177	    emitter.emit(BotEvents.FINALITY_ERROR, "Finalized L2 block time is more than 30 min drifted from L1 clock.");
178	  }
179	
180	  // blockLatestArbToL1Block[0] is the L1 block, blockLatestArbToL1Block[1] is the L2 block (fallsback on latest L2 block if L2 block is not found on L1)
181	  let blockLatestArbToL1Block = await ArbBlockToL1Block(
182	    ArbProvider,
183	    sequencer,
184	    blockLatestArb,
185	    fromBlockEthFinalized,
186	    fromBlockArbFinalized,
187	    true
188	  );
189	
190	  if (finalityIssueFlagArb && !blockLatestArbToL1Block) {
191	    emitter.emit(BotEvents.FINALITY_ERROR, "Arbitrum latest block is not found on L1.");
192	    // this means some issue in the arbitrum node implementation (very bad)
193	    return undefined;
194	  }
195	
196	  // is blockLatestArb is not found on L1, ArbBlockToL1Block fallsback on the latest L2 block found on L1
197	  if (blockLatestArbToL1Block[1] != blockLatestArb.number) {
198	    blockLatestArb = (await ArbProvider.getBlock(blockLatestArbToL1Block[1])) as Block;
199	  }
200	
201	  // ETH POS assumes synchronized clocks
202	  // using local time as a proxy for true "latest" L1 time
203	  const localTimeSeconds = Math.floor(Date.now() / 1000);
204	
205	  // The sequencer is completely offline
206	  if (localTimeSeconds - blockLatestArbToL1Block[0].timestamp > 1800) {
207	    emitter.emit(
208	      BotEvents.FINALITY_ERROR,
209	      "Arbitrum sequencer is offline (from L1 'latest' POV) for atleast 30 minutes."
210	    );
211	    finalityIssueFlagArb = true;
212	  }
213	
214	  // The L2 timestamp is drifted from the L1 timestamp in which the L2 block is posted.
215	  // Not necessarily a problem, but we should know about it
216	  if (Math.abs(blockLatestArbToL1Block[0].timestamp - blockLatestArb.timestamp) > 1800) {
217	    emitter.emit(
218	      BotEvents.FINALITY_ERROR,
219	      `Latest L2 block time is more than 30 min drifted from L1 clock. \n L2 block time: ${blockLatestArb.timestamp}, L1 block time: ${blockLatestArbToL1Block[0].timestamp}, L2 block number: ${blockLatestArb.number}`
220	    );
221	  }
222	
223	  // Note: Using last finalized block as a proxy for the latest finalized epoch
224	  // Using a BeaconChain RPC would be more accurate
225	  if (localTimeSeconds - blockFinalizedEth.timestamp > maxFinalityTimeSecondsEth + finalityBuffer) {
226	    emitter.emit(BotEvents.FINALITY_ERROR, "Ethereum mainnet is experiencing finalization issues.");
227	    finalityIssueFlagEth = true;
228	  }
229	
230	  if (blockFinalizedEth.number < blockFinalizedArbToL1Block[0].number) {
231	    emitter.emit(
232	      BotEvents.FINALITY_ERROR,
233	      "Arbitrum 'finalized' block is posted in an L1 block which is not finalized. Arbitrum node is out of sync with L1 node. It's recommended to use the same L1 RPC as the L1 node used by the Arbitrum node."
234	    );
235	    finalityIssueFlagArb = true;
236	  }
237	  // Always the finalized block: it is the one proven above to sit in a batch
238	  // delivered by a finalized L1 block. blockLatestArb carries the unfinalized
239	  // tail, and callers stake deposits on whatever is returned here.
240	  return [blockFinalizedArb, blockFinalizedEth, finalityIssueFlagArb, finalityIssueFlagEth];
241	};
242	
243	/**
244	 *
245	 * This function finds the corresponding L1(Eth) block for a given L2(Arb) block.
246	 *
247	 * @param L2Provider Arbitrum provider
248	 * @param sequencer Arbitrum sequencerInbox
249	 * @param L2Block L2 block
250	 * @param fromBlockEth from block number on Eth
251	 * @param fromArbBlock from block number on Arb
252	 * @param fallbackLatest fallback to latest L2 block if the L2 block is not found on L1
253	 *
254	 * @returns [L1Block, L2BlockNumberFallback]
255	 */
256	
257	const ArbBlockToL1Block = async (
258	  L2Provider: JsonRpcProvider,
259	  sequencer: SequencerInbox,
260	  L2Block: Block,
261	  fromBlockEth: number,
262	  fromArbBlock: number,
263	  fallbackLatest: boolean
264	): Promise<[Block, number] | undefined> => {
265	  const nodeInterface = NodeInterface__factory.connect(NODE_INTERFACE_ADDRESS, L2Provider);
266	
267	  let latestL2batchOnEth: number;
268	  let latestL2BlockNumberOnEth: number;
269	  let result = (await nodeInterface.functions
270	    .findBatchContainingBlock(L2Block.number, { blockTag: "latest" })
271	    .catch(async (e) => {
272	      // If the L2Block is the latest ArbBlock this will always throw, so we fallback to finding the latest L2 batch and block
273	      if (!fallbackLatest) {
274	        return undefined;
275	      } else {
276	        [latestL2batchOnEth, latestL2BlockNumberOnEth] = await findLatestL2BatchAndBlock(
277	          nodeInterface,
278	          fromArbBlock,
279	          L2Block.number
280	        );
281	      }
282	    })) as any;
283	
284	  const batch = result?.batch?.toNumber() ?? latestL2batchOnEth;
285	  const L2BlockNumberFallback = latestL2BlockNumberOnEth ?? L2Block.number;
286	  /**
287	   * We use the batch number to query the L1 sequencerInbox's SequencerBatchDelivered event
288	   * then, we get its emitted transaction hash.
289	   */
290	  const emittedEvent = await findFirstLog({
291	    contract: sequencer,
292	    filter: sequencer.filters.SequencerBatchDelivered(batch),
293	    fromBlock: fromBlockEth,
294	    toBlock: await sequencer.provider.getBlockNumber(),
295	  });
296	  if (!emittedEvent) {
297	    return undefined;
298	  }
299	
300	  const L1Block = (await emittedEvent.getBlock()) as Block;
301	  return [L1Block, L2BlockNumberFallback];
302	};
303	
304	/**
305	 * This function finds the latest L2 batch and block number that has a corresponding batch on L1.
306	 *
307	 * @param nodeInterface Arbitrum NodeInterface
308	 * @param fromArbBlock from block number on Arb
309	 * @param latestBlockNumber latest block number on Arb
310	 *
